head.script:
scwin.fn_expressionValue = function(rowIdx, col1Value, col2Value) {
    var returnValue = "";
    returnValue = col2Value;
    var rowData = dataList1.getRowData(rowIdx);
    //계산식
    if (col1Value == "sum") {
        gridView1.setCellColor(rowIdx, "col3", "red");
    } else {
        gridView1.setCellColor(rowIdx, "col3", "blue");
    }
    returnValue = WebSquare.util.setNumber(returnValue);
    console.log(col1Value + " : " + col2Value);
    console.log("=====>" + returnValue);
    return returnValue + "_test";
}
scwin.trigger1_onclick = function(e) {
    var jsonData = [{
            "col1": "sum",
            "col2": "12345.00"
        }, {
            "col1": "avg",
            "col2": "123456.894"
        },
        {
            "col1": "sum",
            "col2": "467890.00"
        }, {
            "col1": "avg",
            "col2": "123456.7"
        }
    ];
    dataList1.setJSON(jsonData);
};
scwin.trigger3_onclick = function(e) {
    dataList1.removeAll();
};
scwin.trigger4_onclick = function(e) {
    dataList1.insertRow();
    //dataList1.insertJSON( 0 , [{"col1":"sum", "col2":"6789.00"}] );
};
scwin.trigger5_onclick = function(e) {
    var jsonData = [{
        "col1": "",
        "col2": ""
    }];
    dataList1.setJSON(jsonData);
};
scwin.trigger7_onclick = function(e) {
    dataList1.removeRow(3);
};
scwin.trigger8_onclick = function(e) {
    dataList1.insertRow(2);
};
scwin.trigger9_onclick = function(e) {
    dataList1.removeRows([2, 3]);
};
scwin.isShowData = function() {
    var count = 0;
    WebSquare.wUnit.getJq("#gridView1_body_tbody tr").not(".w2grid_hidedRow").each(function(i, el) {
        if (WebSquare.wUnit.getJq(this).text()) {
            count++;
        }
    });
    return count > 0;
}
scwin.setVal1 = function() {
    return beforeValue1 = WebSquare.wUnit.getObjById('gridView1_cell_3_0').innerText;
}
scwin.setVal2 = function() {
    return beforeValue2 = WebSquare.wUnit.getObjById('gridView1_cell_2_0').innerText;
}
scwin.checkVal1 = function() {
    return WebSquare.wUnit.getObjById('gridView1_cell_3_0').innerText != beforeValue1;
}
scwin.checkVal2 = function() {
    return WebSquare.wUnit.getObjById('gridView1_cell_2_0').innerText != beforeValue2;
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 1. 샘플파일을 실행 후 set버튼을 클릭한다.
    //1. Run the sample file and click the set button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    // verify step 1. data가 셋팅되어 보여진다.
    //1. Data is set and displayed.
    WebSquare.wUnit.addCommand("assert", "scwin.isShowData()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 2. insertRow(2)를 2번 클릭한다.
    //2. Double-click insertRow (2).
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger8').click()");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger8').click()");
    WebSquare.wUnit.addCommand("pause", "1000");
    // verify step 2번째 row에 insertRow가 추가되어진다.
    //2. InsertRow is added to the second row.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gridView1_cell_2_0').innerText == 'undefined_test'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gridView1_cell_3_0').innerText == 'undefined_test'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 3. removeRow(3)을 클릭한다.
    //3. Click removeRow (3).
    WebSquare.wUnit.addCommand("set", "scwin.setVal1()");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger7').click()");
    // verify step 3. 3번째 row가 삭제되어진다.
    //3. The third row is deleted.
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 4. removeRow([2,3])을 클릭한다.
    //4. Click removeRow ([2,3]).
    WebSquare.wUnit.addCommand("set", "scwin.setVal2()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger9').click()");
    // verify step 4. 2번째 row와 3번째 row가 삭제되어진다.
    //4. The second row and the third row are deleted.
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gridView1_cell_3_0').parentElement.style.display", "none");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test
    WebSquare.wUnit.run();
    //stop
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function unitTest
    //Created By: Sang.do
    //Created By: 22-Jan-2018
    window.beforeValue1 = undefined;
    window.beforeValue2 = undefined;
    //end unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
